<?php
defined('ABSPATH') || exit;
final class GE_Work_Finance_UI {
    public static function render($order) {
        $balance=GE_Work_Finance::balance($order);$error=get_transient('ge_work_finance_error_'.get_current_user_id().'_'.$order->get_id());
        if($error){echo '<p class="ge-production-notice is-error" role="alert">'.esc_html($error).'</p>';delete_transient('ge_work_finance_error_'.get_current_user_id().'_'.$order->get_id());}
        if(($_GET['work_payment']??'')==='saved')echo '<p class="ge-production-notice" role="status">Pago registrado. Acreditado y saldo ya están actualizados.</p>';
        if(is_wp_error($balance)){echo '<p role="alert">'.esc_html($balance->get_error_message()).'</p>';return;}
        if(GE_Work_Finance::can_write(get_current_user_id()) && $balance['amount_due_cents']>0){
            $pending=GE_Work_Finance::pending_attempt($order);
            if($pending)echo '<p>Hay un intento de cobro pendiente #'.absint($pending).'. Revisalo en los comprobantes del portal antes de registrar otro pago.</p>';
            else {
                echo '<section class="ge-work-payment-entry"><h3>Registrar dinero recibido</h3><p>Registrá el importe acreditado, incluso si el cliente pagó fuera del portal. No cambia el precio acordado ni libera producción automáticamente.</p><form class="ge-admin-form" data-ge-work-payment method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ge_work_manual_payment"><input type="hidden" name="order_id" value="'.$order->get_id().'"><input type="hidden" name="request_id" value="'.esc_attr(wp_generate_uuid4()).'"><input type="hidden" name="scope" value="'.esc_attr(GE_Work_Finance::scope($order,$balance)).'">';wp_nonce_field('ge_work_payment_'.$order->get_id());
                echo '<fieldset><legend>Pago recibido</legend><label><input type="radio" name="kind" value="partial" checked> Pago parcial / otro importe</label><label><input type="radio" name="kind" value="full"> Saldo completo · '.esc_html(GE_Work_Finance::money($balance['amount_due_cents'],$order->get_currency())).'</label></fieldset><label>Importe recibido ('.$order->get_currency().')<input type="number" name="amount" min="0.01" step="0.01" max="'.esc_attr(GE_WTP_Quote_Balance::decimal($balance['amount_due_cents'])).'" placeholder="Ej.: 165000.00"><small>Se usa sólo para pago parcial. Saldo completo registra lo que resta, sin duplicar pagos anteriores.</small></label><label>Fecha de recepción<input type="date" name="received_date" required max="'.esc_attr(wp_date('Y-m-d')).'" value="'.esc_attr(wp_date('Y-m-d')).'"></label><label>Medio de pago<select name="method" required><option value="">Elegir</option><option value="transfer">Transferencia acreditada</option><option value="cash">Efectivo recibido</option><option value="other">Otro medio verificado</option></select></label><label>Referencia / número de operación<input name="reference" maxlength="160"><small>Obligatoria para transferencia y otro medio.</small></label><label>Observación<textarea name="note" maxlength="1000" rows="2"></textarea></label><label><input type="checkbox" name="verified" value="1" required> Verifiqué que este dinero fue recibido. Un comprobante cargado no alcanza para acreditar el pago.</label><button class="ge-staff-button" type="submit">Registrar pago acreditado</button></form></section>';
            }
        } elseif(!$balance['amount_due_cents'])echo '<p><strong>Pedido pagado completo.</strong></p>';
        if($balance['ledger']){echo '<section><h3>Historial de cobros registrados</h3><ul>';foreach(array_reverse($balance['ledger']) as $entry){$actor=get_userdata($entry['actor']);echo '<li><strong>'.esc_html(GE_Work_Finance::money($entry['amount_cents'],$entry['currency'])).'</strong> · '.esc_html($entry['received_date']).' · '.esc_html(array('cash'=>'Efectivo','transfer'=>'Transferencia','other'=>'Otro medio')[$entry['method']]).' · '.esc_html($entry['reference']).'<small> Registrado por '.esc_html($actor?$actor->display_name:'#'.$entry['actor']).'</small></li>';}echo '</ul></section>';}
    }
}
